const ExcelJS = require('exceljs');
const path = require('path');

async function main() {
  const wb = new ExcelJS.Workbook();

  // === Sheet 1: Raw Data (原始数据) ===
  const rawSheet = wb.addWorksheet('Raw Data 原始数据');

  // Bilingual headers
  const headerRow = rawSheet.addRow(['Team 团队', 'Amount 金额']);
  headerRow.eachCell((cell) => {
    cell.font = { name: '微软雅黑', size: 11, bold: true };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF4472C4' } };
    cell.font = { name: '微软雅黑', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.border = {
      top: { style: 'thin' }, bottom: { style: 'thin' },
      left: { style: 'thin' }, right: { style: 'thin' }
    };
  });

  // 3 original records from CSV
  const records = [
    ['A', 10],
    ['A', 20],
    ['B', 12]
  ];

  records.forEach(([team, amount]) => {
    const row = rawSheet.addRow([team, amount]);
    row.eachCell((cell) => {
      cell.font = { name: '微软雅黑', size: 11 };
      cell.alignment = { horizontal: 'center', vertical: 'middle' };
      cell.border = {
        top: { style: 'thin' }, bottom: { style: 'thin' },
        left: { style: 'thin' }, right: { style: 'thin' }
      };
    });
  });

  // Set column widths for Chinese characters
  rawSheet.getColumn(1).width = 18;
  rawSheet.getColumn(2).width = 18;

  // === Sheet 2: Summary (汇总) ===
  const sumSheet = wb.addWorksheet('Summary 汇总');

  // Bilingual headers for summary
  const sumHeaderRow = sumSheet.addRow(['Team 团队', 'Total Amount 合计金额']);
  sumHeaderRow.eachCell((cell) => {
    cell.font = { name: '微软雅黑', size: 11, bold: true };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF4472C4' } };
    cell.font = { name: '微软雅黑', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.border = {
      top: { style: 'thin' }, bottom: { style: 'thin' },
      left: { style: 'thin' }, right: { style: 'thin' }
    };
  });

  // Team A summary with SUM formula and cached result
  // In Raw Data sheet, A records are rows 2 and 3 (B2=10, B3=20)
  const teamARow = sumSheet.addRow(['A', null]);
  teamARow.getCell(1).font = { name: '微软雅黑', size: 11 };
  teamARow.getCell(1).alignment = { horizontal: 'center', vertical: 'middle' };
  teamARow.getCell(1).border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };
  // SUM formula referencing Raw Data sheet, with cached result = 30
  const cellA = teamARow.getCell(2);
  cellA.value = { formula: "SUM('Raw Data 原始数据'!B2:B3)", result: 30 };
  cellA.font = { name: '微软雅黑', size: 11 };
  cellA.alignment = { horizontal: 'center', vertical: 'middle' };
  cellA.border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };

  // Team B summary with SUM formula and cached result
  // In Raw Data sheet, B record is row 4 (B4=12)
  const teamBRow = sumSheet.addRow(['B', null]);
  teamBRow.getCell(1).font = { name: '微软雅黑', size: 11 };
  teamBRow.getCell(1).alignment = { horizontal: 'center', vertical: 'middle' };
  teamBRow.getCell(1).border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };
  const cellB = teamBRow.getCell(2);
  cellB.value = { formula: "SUM('Raw Data 原始数据'!B4:B4)", result: 12 };
  cellB.font = { name: '微软雅黑', size: 11 };
  cellB.alignment = { horizontal: 'center', vertical: 'middle' };
  cellB.border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };

  // Grand Total row with SUM formula and cached result = 42
  const totalRow = sumSheet.addRow(['Total 总计', null]);
  totalRow.getCell(1).font = { name: '微软雅黑', size: 11, bold: true };
  totalRow.getCell(1).alignment = { horizontal: 'center', vertical: 'middle' };
  totalRow.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD9E2F3' } };
  totalRow.getCell(1).border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };
  const cellTotal = totalRow.getCell(2);
  cellTotal.value = { formula: 'SUM(B2:B3)', result: 42 };
  cellTotal.font = { name: '微软雅黑', size: 11, bold: true };
  cellTotal.alignment = { horizontal: 'center', vertical: 'middle' };
  cellTotal.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD9E2F3' } };
  cellTotal.border = {
    top: { style: 'thin' }, bottom: { style: 'thin' },
    left: { style: 'thin' }, right: { style: 'thin' }
  };

  // Set column widths
  sumSheet.getColumn(1).width = 18;
  sumSheet.getColumn(2).width = 22;

  // Write file
  const outDir = process.env.SKILL_SANDBOX_OUT_DIR || '/workspace';
  const outPath = path.join(outDir, 'sales.xlsx');
  await wb.xlsx.writeFile(outPath);
  console.log('Created:', outPath);
}

main().catch(err => { console.error(err); process.exit(1); });

const ExcelJS = require('exceljs');

async function main() {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile('/workspace/sales.xlsx');

  console.log('=== Sheets:', wb.worksheets.map(s => s.name));

  // Verify Raw Data sheet
  const rawSheet = wb.getWorksheet('Raw Data 原始数据');
  console.log('\n=== Raw Data 原始数据 ===');
  rawSheet.eachRow((row, rowNum) => {
    const vals = [];
    row.eachCell({ includeEmpty: true }, (cell, colNum) => {
      if (colNum <= 2) {
        const v = cell.value;
        if (v && typeof v === 'object' && v.formula) {
          vals.push(`formula:${v.formula}|result:${v.result}`);
        } else {
          vals.push(v);
        }
      }
    });
    console.log(`Row ${rowNum}: [${vals.join(', ')}]`);
  });

  // Verify Summary sheet
  const sumSheet = wb.getWorksheet('Summary 汇总');
  console.log('\n=== Summary 汇总 ===');
  sumSheet.eachRow((row, rowNum) => {
    const vals = [];
    row.eachCell({ includeEmpty: true }, (cell, colNum) => {
      if (colNum <= 2) {
        const v = cell.value;
        if (v && typeof v === 'object' && v.formula) {
          vals.push(`formula:${v.formula}|result:${v.result}`);
        } else {
          vals.push(v);
        }
      }
    });
    console.log(`Row ${rowNum}: [${vals.join(', ')}]`);
  });

  // Specific checks
  console.log('\n=== Validation Checks ===');
  const b2 = sumSheet.getCell('B2').value;
  const b3 = sumSheet.getCell('B3').value;
  const b4 = sumSheet.getCell('B4').value;

  console.log('Team A formula:', b2.formula, '| cached result:', b2.result, '| expected: 30 |', b2.result === 30 ? 'PASS' : 'FAIL');
  console.log('Team B formula:', b3.formula, '| cached result:', b3.result, '| expected: 12 |', b3.result === 12 ? 'PASS' : 'FAIL');
  console.log('Total formula:', b4.formula, '| cached result:', b4.result, '| expected: 42 |', b4.result === 42 ? 'PASS' : 'FAIL');

  // Check raw data has 3 records
  let rawCount = 0;
  rawSheet.eachRow((row, rowNum) => { if (rowNum > 1) rawCount++; });
  console.log('Raw data records:', rawCount, '| expected: 3 |', rawCount === 3 ? 'PASS' : 'FAIL');
}

main().catch(err => { console.error(err); process.exit(1); });

